/**
 * Next per-project issue number. Archived issues keep their number, so the
 * max is taken over every row rather than the live ones.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const db = getDb();
  const row = db
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  const sequence = db
    .select({ value: projectIssueSequences.lastNumber })
    .from(projectIssueSequences)
    .where(eq(projectIssueSequences.projectId, projectId))
    .get();
  return Math.max(row?.value ?? 0, sequence?.value ?? 0) + 1;
}

async function rememberIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
  number: number,
): Promise<void> {
  getDb()
    .insert(projectIssueSequences)
    .values({ orgId, projectId, lastNumber: number })
    .onConflictDoUpdate({
      target: projectIssueSequences.projectId,
      set: {
        lastNumber: sql`max(${projectIssueSequences.lastNumber}, excluded.last_number)`,
      },
    })
    .run();
}

