export const projectMembers = sqliteTable(
  "project_members",
  {
    ...tenantColumns,
    projectId: text("project_id").notNull(),
    userId: text("user_id").notNull(),
    addedAt: text("added_at").notNull(),
  },
  (table) => [
    uniqueIndex("project_members_pk").on(table.projectId, table.userId),
    index("project_members_org_idx").on(table.orgId),
  ],
);

/** High-water issue number retained after old issue rows are purged. */
export const projectIssueSequences = sqliteTable(
  "project_issue_sequences",
  {
    orgId: text("org_id").notNull(),
    projectId: text("project_id").notNull(),
    lastNumber: integer("last_number").notNull(),
  },
  (table) => [uniqueIndex("project_issue_sequences_pk").on(table.projectId)],
);

